style.css:
@-moz-document domain("youtube.com") {
/* 1. Разрешаем элементам выходить за рамки полосы, чтобы неон не обрезался */
    .ytp-progress-bar-container, .ytp-progress-bar, .ytp-chrome-bottom {
        overflow: visible !important;
    }

    /* 2. Супер-яркая неоновая неоново-красная полоса с тройным свечением */
    .ytp-play-progress {
        background: linear-gradient(90deg, #ff0055, #ff0000) !important;
        box-shadow: 0 0 12px #ff0033, 0 0 25px #ff0000, 0 0 35px #ff0033 !important;
        filter: brightness(1.5) contrast(1.2) !important;
    }

    /* 3. Принудительно выводим маску самурая на передний план с собственным неоновым ореолом */
    .ytp-scrubber-container {
        background-image: url('https://postimg.cc') !important;
        background-size: contain !important;
        background-repeat: no-repeat !important;
        background-position: center !important;
        width: 32px !important; /* Немного увеличили размер для заметности */
        height: 32px !important;
        margin-top: -8px !important; /* Корректировка центрирования под новый размер */
        display: block !important;
        opacity: 1 !important;
        z-index: 9999 !important; /* Выталкиваем маску поверх всех слоев плеера */
        
        /* Мощный неоновый контур вокруг маски */
        filter: drop-shadow(0 0 6px #ff0033) drop-shadow(0 0 15px #ff0000) brightness(1.5) !important;
    }

    /* 4. На всякий случай зачищаем старый круглый ползунок */
    .ytp-scrubber-button {
        background: transparent !important;
        border: none !important;
        box-shadow: none !important;
    }
}
